command:
set +e
W=$(pwd)
git submodule update --init --depth 1 3rdparty/freetype >/dev/null 2>&1
cmake -S 3rdparty/freetype -B /tmp/ftnew -G Ninja -DCMAKE_BUILD_TYPE=Release -DFT_DISABLE_ZLIB=ON -DFT_DISABLE_BZIP2=ON -DFT_DISABLE_PNG=ON -DFT_DISABLE_HARFBUZZ=ON -DFT_DISABLE_BROTLI=ON >/dev/null && cmake --build /tmp/ftnew >/dev/null && echo new-ok
cd /tmp
curl -sL -o ft.tgz https://download.savannah.gnu.org/releases/freetype/freetype-old/freetype-2.4.12.tar.gz && tar xzf ft.tgz
(cd freetype-2.4.12 && ./configure --prefix=/tmp/ft2412 --without-zlib --without-bzip2 -q >/dev/null 2>&1 && make -j4 -s >/dev/null 2>&1 && make install -s >/dev/null 2>&1) && echo old-ok
find /tmp/ft2412/include -name ft2build.h
cat > trig.c <<'EOF'
#include <ft2build.h>
#include FT_FREETYPE_H
#include FT_TRIGONOMETRY_H
#include <stdio.h>
#include <stdint.h>
static uint64_t h = 1469598103934665603ULL;
static void mix(int64_t v){ h ^= (uint64_t)v; h *= 1099511628211ULL; }
static uint64_t s = 0x9E3779B97F4A7C15ULL;
static uint64_t rnd(void){ s ^= s << 13; s ^= s >> 7; s ^= s << 17; return s; }
int main(int argc, char** argv){
  const char* f = argv[1];
  const int64_t full = 360L << 16;
  int chunk = 0;
  if (f[0]=='s' || f[0]=='t' || f[0]=='u') {
    for (int64_t a = -full; a <= full; a++) {
      if (f[0]=='s') mix(FT_Sin(a));
      else if (f[0]=='t') mix(FT_Tan(a));
      else { FT_Vector v; FT_Vector_Unit(&v, a); mix(v.x); mix(v.y); }
      if (((a + full) & 0xFFFF) == 0xFFFF) { printf("%d %016llx\n", chunk++, (unsigned long long)h); }
    }
  } else {
    for (int i = 0; i < 20000000; i++) {
      int64_t m = (i % 4 == 0) ? 0xFF : (i % 4 == 1) ? 0xFFFF : (i % 4 == 2) ? 0xFFFFFF : 0x3FFFFFFF;
      int64_t x = (int64_t)(rnd() % (2*m+1)) - m, y = (int64_t)(rnd() % (2*m+1)) - m;
      int64_t ang = (int64_t)(rnd() % (4*full)) - 2*full;
      FT_Vector v = {x, y};
      if (f[0]=='r') { FT_Vector_Rotate(&v, ang); mix(v.x); mix(v.y); }
      else if (f[0]=='l') { mix(FT_Vector_Length(&v)); }
      else if (f[0]=='p') { FT_Fixed len; FT_Angle an; FT_Vector_Polarize(&v, &len, &an); mix(len); mix(an); }
      else if (f[0]=='f') { FT_Vector o; FT_Vector_From_Polar(&o, x < 0 ? -x : x, ang); mix(o.x); mix(o.y); }
      if (i % 1000000 == 999999) printf("%d %016llx\n", chunk++, (unsigned long long)h);
    }
  }
  return 0;
}
EOF
gcc -O2 -o trig_old trig.c -I/tmp/ft2412/include -I/tmp/ft2412/include/freetype2 /tmp/ft2412/lib/libfreetype.a -lm && echo built-old
gcc -O2 -o trig_new trig.c -I$W/3rdparty/freetype/include -I/tmp/ftnew/include /tmp/ftnew/libfreetype.a -lm && echo built-new
for fn in sin tan unit rotate length polarize from; do
  ./trig_old $fn > o_$fn.txt & ./trig_new $fn > n_$fn.txt & wait
  echo "$fn: chunks=$(wc -l < o_$fn.txt)/$(wc -l < n_$fn.txt) first_diff=$(diff o_$fn.txt n_$fn.txt | grep -m1 '^<')"
done

